long long ways[20][200];   // ways[k][s]: k free digits with digit sum s

int main() {
    ways[0][0] = 1;
    for (int k = 1; k < 20; k++)
        for (int s = 0; s < 200; s++)
            for (int d = 0; d <= 9 && d <= s; d++) ways[k][s] += ways[k - 1][s - d];
    long long N;
    int S;
    cin >> N >> S;
    string digits = to_string(N);
    int len = digits.size(), used = 0;
    long long total = 0;
    for (int i = 0; i < len; i++) {
        int here = digits[i] - '0';
        for (int d = 0; d < here; d++)               // smaller digit here, everything after is free
            if (S - used - d >= 0) total += ways[len - i - 1][S - used - d];
        used += here;
    }
    if (used == S) total++;                           // N itself
    cout << total << "\n";                            // 0 is never counted because S >= 1
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<vector<long long>> cost(n, vector<long long>(n));
    for (auto &row : cost)
        for (auto &x : row) scanf("%lld", &x);
    const long long INF = LLONG_MAX / 4;
    vector<long long> best(1 << n, INF);
    best[0] = 0;
    for (int mask = 0; mask < (1 << n) - 1; mask++) {
        if (best[mask] == INF) continue;
        int person = __builtin_popcount(mask);          // the next person to be given a job
        for (int job = 0; job < n; job++)
            if (!(mask >> job & 1))
                best[mask | 1 << job] = min(best[mask | 1 << job], best[mask] + cost[person][job]);
    }
    printf("%lld\n", best[(1 << n) - 1]);
}

