        long long x;
        scanf("%lld", &x);
        pre[i] = pre[i - 1] + x;
    }
    vector<vector<long long>> best(n + 2, vector<long long>(n + 2, 0));
    for (int len = 2; len <= n; len++)
        for (int l = 1; l + len - 1 <= n; l++) {
            int r = l + len - 1;
            best[l][r] = LLONG_MAX;
            for (int k = l; k < r; k++)                 // the last merge joins [l, k] and [k + 1, r]
                best[l][r] = min(best[l][r], best[l][k] + best[k + 1][r]);
            best[l][r] += pre[r] - pre[l - 1];
        }
    printf("%lld\n", best[1][n]);
}

