    vector<int> borders;
    for (int k = pi[n - 1]; k > 0; k = pi[k - 1]) borders.push_back(k);
    reverse(borders.begin(), borders.end());
    for (size_t i = 0; i < borders.size(); i++) printf("%d%c", borders[i], i + 1 == borders.size() ? '\n' : ' ');
    if (borders.empty()) puts("");
}

