int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<int> parent(n + 1, 0), order = {1};
    parent[1] = -1;
    for (size_t i = 0; i < order.size(); i++)
        for (int u : adj[order[i]])
            if (u != parent[order[i]]) { parent[u] = order[i]; order.push_back(u); }
    vector<long long> size(n + 1, 1), down(n + 1, 0), answer(n + 1, 0);
    for (int i = n - 1; i >= 1; i--) {                    // bottom-up: sizes and distances into each subtree
        int v = order[i], p = parent[v];
        size[p] += size[v];
        down[p] += down[v] + size[v];
    }
    answer[1] = down[1];
    for (int i = 1; i < n; i++) {                          // top-down: move the root across each edge
        int v = order[i];
        answer[v] = answer[parent[v]] - size[v] + (n - size[v]);
    }
    for (int v = 1; v <= n; v++) printf("%lld%c", answer[v], v == n ? '\n' : ' ');
}

