int main() {
    const long long M = 1000000007;
    int t;
    scanf("%d", &t);
    vector<int> heights(t);
    for (auto &h : heights) scanf("%d", &h);
    int top = *max_element(heights.begin(), heights.end());
    vector<long long> ways(top + 1);
    long long wide = 1, split = 1;                      // by the shape of the top row
    ways[1] = 2;
    for (int i = 2; i <= top; i++) {
        long long w = (2 * wide + split) % M, s = (wide + 4 * split) % M;
        wide = w; split = s;
        ways[i] = (wide + split) % M;
    }
    for (int h : heights) printf("%lld\n", ways[h]);
}

